df = pd.read_csv('data.csv')
X_vars = ['log_hist_days','region','log_pre_gmv','orders','cat_share','tenure','tier','dY_placebo']
X = df[X_vars].values
D = df['D'].values
Y = df['dY'].values

def model_factory(kind, seed):
    if kind=='lgb':
        return lgb.LGBMRegressor(n_estimators=300, learning_rate=0.05, num_leaves=31, min_child_samples=50, random_state=seed, verbose=-1)
    if kind=='hgb':
        return HistGradientBoostingRegressor(max_iter=300, learning_rate=0.05, max_leaf_nodes=31, min_samples_leaf=50, random_state=seed)
    if kind=='rf':
        return RandomForestRegressor(n_estimators=500, min_samples_leaf=5, random_state=seed, n_jobs=-1)
    if kind=='linear':
        return LinearRegression()
    if kind=='ridge':
        return RidgeCV(alphas=np.logspace(-2,2,20))
    if kind=='lasso':
        return LassoCV(alphas=np.logspace(-3,1,20), cv=3, random_state=seed, max_iter=10000)

def dml(kind, n_splits=5, seed=0):
    kf = KFold(n_splits=n_splits, shuffle=True, random_state=seed)
    resD=np.zeros_like(D); resY=np.zeros_like(Y)
    for tr,te in kf.split(X):
        md = model_factory(kind, seed); md.fit(X[tr], D[tr])
        my = model_factory(kind, seed); my.fit(X[tr], Y[tr])
        resD[te]=D[te]-md.predict(X[te])
        resY[te]=Y[te]-my.predict(X[te])
    m = sm.OLS(resY, sm.add_constant(resD)).fit()
    return m.params[1], m.bse[1]
for kind in ['linear','ridge','lgb','hgb','rf']:
    coef, se = dml(kind)
    print(kind, 'theta', coef, 'se', se, 'effect', -2*coef)

