import pandas as pd, numpy as np, lightgbm as lgb
from sklearn.model_selection import KFold
from sklearn.ensemble import HistGradientBoostingRegressor
from sklearn.linear_model import LinearRegression, RidgeCV
from sklearn.preprocessing import SplineTransformer
from sklearn.pipeline import make_pipeline

df=pd.read_csv('data.csv')
base_withP=['D','log_hist_days','region','log_pre_gmv','orders','cat_share','tenure','tier','dY_placebo']
base_noP=['D','log_hist_days','region','log_pre_gmv','orders','cat_share','tenure','tier']

def model_factory(kind, seed):
    if kind=='lgb':
        return lgb.LGBMRegressor(n_estimators=400, learning_rate=0.04, num_leaves=31, min_child_samples=50, subsample=0.8, colsample_bytree=0.8, random_state=seed, verbose=-1)
    if kind=='hgb':
        return HistGradientBoostingRegressor(max_iter=400, learning_rate=0.04, max_leaf_nodes=31, min_samples_leaf=50, l2_regularization=1.0, random_state=seed)
    if kind=='linear':
        return LinearRegression()
    if kind=='ridge':
        return make_pipeline(SplineTransformer(n_knots=5, degree=3), RidgeCV(alphas=np.logspace(-3,3,20)))

def pd_effect(kind, X, ycol, d0=10, d1=12, n_splits=5, seed=0):
    Y=df[ycol].values
    kf=KFold(n_splits=n_splits, shuffle=True, random_state=seed)
    p0=np.zeros(len(Y)); p1=np.zeros(len(Y))
    for tr,te in kf.split(X):
        m=model_factory(kind, seed); m.fit(X.iloc[tr], Y[tr])
        Xte=X.iloc[te].copy()
        X0=Xte.copy(); X0['D']=d0; p0[te]=m.predict(X0)
        X1=Xte.copy(); X1['D']=d1; p1[te]=m.predict(X1)
    diff=p0-p1
    return diff.mean(), diff.std()/np.sqrt(len(diff))

for kind in ['lgb','hgb','linear','ridge']:
    eff_dy,_=pd_effect(kind, df[base_withP], 'dY', seed=0)
    eff_pl,_=pd_effect(kind, df[base_noP], 'dY_placebo', seed=0)
    print(kind, 'dY effect', round(eff_dy,4), 'placebo effect', round(eff_pl,4))
